def preserve_existing_goal_progress(apps, schema_editor):
    Goal = apps.get_model('goals', 'Goal')
    GoalContribution = apps.get_model('goals', 'GoalContribution')
    now = django.utils.timezone.now()
    today = django.utils.timezone.localdate()
    for goal in Goal.objects.all().iterator():
        update_fields = []
        if goal.progress and goal.progress > 0:
            GoalContribution.objects.get_or_create(
                owner_id=goal.owner_id,
                idempotency_key=f'migration:goal-opening:{goal.pk}',
                defaults={
                    'goal_id': goal.pk,
                    'account_id': goal.account_id,
                    'amount': goal.progress,
                    'contributed_on': today,
                    'source': 'opening_balance',
                    'note': 'Progress preserved during contribution ledger migration.',
                },
            )
        if goal.progress >= goal.target_amount:
            goal.status = 'completed'
            goal.active = False
            goal.completed_at = now
            update_fields.extend(['status', 'active', 'completed_at'])
        elif not goal.active:
            goal.status = 'paused'
            update_fields.append('status')
        if update_fields:
            goal.save(update_fields=update_fields)


